{
  "items": [
    {
      "title": "Destatis GENESIS-Online: Migration Between Germany and Foreign Countries by Year and Citizenship (2000–2025)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/url/b2eb042c",
      "justification": "Official dataset from the German Federal Statistical Office (Destatis), table 12711-0007. Provides annual immigration, emigration, and net migration figures by nationality. Covers the entire 2010s and much of the 2020s, making it particularly useful for analyzing migration trends, the 2015 refugee influx, and migration following Russia's invasion of Ukraine in 2022."
    },
    {
      "title": "Destatis: Migration Flows in Germany — Historical and Monthly Statistics",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Society-Environment/Population/Migration/Tables/_tables.html",
      "justification": "Official collection of German migration statistics covering immigration, emigration, and internal migration. Includes historical annual migration figures dating back to 1950, monthly migration statistics, breakdowns by nationality and country of origin or destination, and migration across German federal states. Particularly suitable for time-series analysis of migration during the 2010s and 2020s."
    },
    {
      "title": "Eurostat: Immigration by Age Group, Sex and Citizenship",
      "url_or_doi": "https://doi.org/10.2908/migr_imm1ctz",
      "justification": "Harmonized European statistical dataset containing annual immigration figures by age, sex, and citizenship. Covers 1998–2024 and includes Germany. Enables analysis of demographic characteristics of immigrants arriving in Germany during the 2010s and 2020s, as well as comparisons with other European countries. Dataset code: migr_imm1ctz."
    },
    {
      "title": "Eurostat: International Migration and Citizenship Statistics",
      "url_or_doi": "https://ec.europa.eu/eurostat/en/web/migration-asylum/international-migration-citizenship/information-data",
      "justification": "Official Eurostat data portal providing access to harmonized migration datasets for Germany and other European countries. Includes immigration, emigration, citizenship, country of birth, country of previous residence, age, and sex. Useful for comparing Germany's migration patterns with those of other EU countries throughout the 2010s and 2020s."
    },
    {
      "title": "IAB-BAMF-SOEP Survey of Refugees in Germany",
      "url_or_doi": "https://fdz.iab.de/en/pd_hd/iab-bamf-soep-survey-of-refugees-version-1623-v1/",
      "justification": "Representative longitudinal survey conducted jointly by the Institute for Employment Research (IAB), the Federal Office for Migration and Refugees (BAMF), and the German Socio-Economic Panel (SOEP). Provides detailed individual-level information on refugees living in Germany, including employment, education, language proficiency, integration, household characteristics, and living conditions. Especially valuable for studying refugee integration following the 2015–2016 migration crisis. Research data access conditions apply."
    },
    {
      "title": "DIW Berlin: IAB-BAMF-SOEP Survey of Refugees — Data Editions",
      "url_or_doi": "https://www.diw.de/en/diw_01.c.795950.en/",
      "justification": "Official data catalog for successive releases of the IAB-BAMF-SOEP refugee survey, including more recent survey editions. Provides access information and documentation for longitudinal research on refugees in Germany. Suitable for studying how employment, education, social integration, and economic circumstances evolved from the mid-2010s into the 2020s."
    },
    {
      "title": "DIW Berlin: IAB-BAMF-SOEP Survey of Refugees — Research Project and Data Access",
      "url_or_doi": "https://www.diw.de/en/diw_01.c.930532.en/%26",
      "justification": "Research project focusing on people who migrated to Germany seeking protection from persecution and armed conflict. Provides information on representative survey data collected through collaboration between DIW Berlin, IAB, and BAMF. Particularly useful for studying the socioeconomic integration of refugees during the 2010s and 2020s. Some linked administrative datasets require restricted research access."
    },
    {
      "title": "Destatis: Migration Flows — Immigration and Emigration in Germany",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Society-Environment/Population/Migration/_node.html",
      "justification": "Official German statistical portal providing migration indicators, methodological explanations, and access to GENESIS-Online datasets. Includes information about immigration to Germany, emigration from Germany, net migration, nationality, and countries of origin and destination. Particularly useful for identifying relevant statistical tables and obtaining consistent annual migration figures for 2010–2025."
    },
    {
      "title": "Destatis: Migration and Emigration Statistics — German-Language Data Portal",
      "url_or_doi": "https://www.destatis.de/DE/Themen/Gesellschaft-Umwelt/Bevoelkerung/Wanderungen/_inhalt.html",
      "justification": "German-language official data portal covering international and internal migration. Provides access to detailed migration statistics, including geographic migration patterns and movements between German regions. Useful for investigating urban-to-rural migration, migration between federal states, and international migration during the 2010s and 2020s."
    },
    {
      "title": "Federal Office for Migration and Refugees (BAMF): Migration Report 2023",
      "url_or_doi": "https://www.bamf.de/SharedDocs/Anlagen/EN/Forschung/Migrationsberichte/migrationsbericht-2023-kurzfassung.pdf?__blob=publicationFile&v=9",
      "justification": "Official German government migration report containing statistical tables and indicators derived from Destatis, BAMF, and the Central Register of Foreigners. Covers immigration, emigration, asylum-related migration, and other migration categories. Particularly useful for understanding migration developments during the early 2020s. The report is a statistical publication rather than a standalone machine-readable dataset."
    },
    {
      "title": "BAMF: Migration Report 2020 — Key Findings",
      "url_or_doi": "https://www.bamf.de/SharedDocs/Anlagen/EN/Forschung/Migrationsberichte/migrationsbericht-2020-zentrale-ergebnisse.pdf?__blob=publicationFile&v=9",
      "justification": "Official German government publication containing statistical information on migration between Germany and other countries. Includes immigration, emigration, and net migration trends from 2010 to 2020, particularly for foreign nationals. Useful for studying changes in migration during the 2015 refugee crisis and the beginning of the COVID-19 pandemic. Also documents methodological changes affecting comparisons across years."
    },
    {
      "title": "BAMF: The Federal Office in Figures 2024 (Das Bundesamt in Zahlen)",
      "url_or_doi": "https://www.bamf.de/SharedDocs/Anlagen/DE/Statistik/BundesamtinZahlen/bundesamt-in-zahlen-2024.pdf?__blob=publicationFile&v=3",
      "justification": "Official statistical report from Germany's Federal Office for Migration and Refugees. Contains detailed figures on asylum applications, migration, and related administrative developments. Includes historical comparisons covering the 2010s and 2020s, particularly the migration increases associated with 2015 and 2022. Useful for studying asylum-related migration patterns and changes in the composition of migration to Germany."
    },
    {
      "title": "Destatis: GENESIS-Online Open Data and API",
      "url_or_doi": "https://www.destatis.de/EN/Service/OpenData/api-webservice.html",
      "justification": "Official access point for the German Federal Statistical Office's machine-readable statistical datasets. Provides information about retrieving GENESIS-Online data through an API or web interface. Particularly useful for researchers building reproducible migration datasets, downloading annual or monthly migration statistics, and automating analyses covering the 2010s and 2020s. This is a data-access service rather than a migration-specific dataset."
    },
    {
      "title": "Eurostat-Based Migration Statistics: Germany Migration Atlas",
      "url_or_doi": "https://migrationatlas.eu/en/countries/germany/",
      "justification": "Country-specific migration statistics portal presenting Germany's immigration, emigration, and net migration indicators using European statistical data. Useful for quickly examining migration trends, identifying major changes during the 2010s and 2020s, and comparing Germany with other European countries. Serves as a supplementary source for visualization and exploration rather than a replacement for original Eurostat datasets."
    }
  ]
}
